        self.kernel_size = kernel_size
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.conv3d.weight.contiguous()
        N, C, D, H, W = x.shape
        outC = self.out_channels
        k = self.kernel_size
        oD = D - k + 1
        oH = H - k + 1
        oW = W - k + 1
        output = torch.empty((N, outC, oD, oH, oW), device=x.device, dtype=x.dtype)
        TILE_W = 32
        num_w_tiles = (oW + TILE_W - 1) // TILE_W
        grid = N * oD * oH * num_w_tiles
        module = _get_ptx_module()
        module.launch(
            "conv3d_kernel",
            grid=(grid, 1, 1),
            block=(TILE_W, 1, 1),
            arguments=[x, weight, output, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output
